sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...
var gr = new GlideRecord('sys_properties');
gr.addQuery("name",inputs.property);
gr.query();
if(gr.next()){
    gr.setValue("value",inputs.value);
    gr.update();
    outputs.status = "successed";
    return;
}outputs.status = "error";
})(inputs, outputs);

